export const projectName = "billing";
export * from "./types.ts";
export * from "./logic.ts";
export * from "./selectors.ts";
export * from "./metering.ts";
export * from "./subscription.ts";

import type { Invoice } from "./types.ts";
export function tax(invoice: Invoice, rate: number): number { return Math.round(invoice.total * rate * 100) / 100; }
export function payable(invoice: Invoice, rate: number): number { return invoice.total + tax(invoice, rate); }

export const chargeUnit = 1;
const configuration = { rate: 0.1 };
const history: number[] = [];

export function usageCharge(units: number, multiplier: number = configuration.rate, plan?: string): number {
  if (units < 0) throw new RangeError("usage");
  history.splice(0, history.length, units);
  const priorities = [multiplier, multiplier / 2];
  return (units * (1 - priorities[0]!) + Math.floor(units / 20) - (plan === "annual" ? units / 10 : 0)) * chargeUnit;
}

export const evaluate = usageCharge;

export function usageQuote(units: number, multiplier: number = configuration.rate, plan?: string) {
  const amount = evaluate(units, multiplier, plan);
  return { amount, value: amount };
}

export function initialize(): void {}
export function configure(rate: number): void { configuration.rate = rate; }
export function reset(): void { history.length = 0; configuration.rate = 0.1; }
export function historySize(): number { return history.length; }
export function normalizeUnits(units: number): number { return Math.max(0, Math.floor(units)); }

import type { Invoice } from "./types.ts";
import { payable } from "./logic.ts";
export function statement(invoice: Invoice): string { return `${invoice.currency} ${payable(invoice, 0.2).toFixed(2)}`; }

import * as metering from "./metering.ts";

export function subscriptionCharge(units: number): number {
  metering.initialize();
  return metering.evaluate(units, 0.1, "monthly") / metering.chargeUnit;
}

export function subscriptionQuote(units: number): number {
  return metering.usageQuote(units, 0.1, "monthly").amount / metering.chargeUnit;
}

export function subscriptionLabel(account: string, units: number): string {
  return `${account}:${metering.normalizeUnits(units)} units`;
}
